            $classesData = $data['classes'];
            unset($data['classes']);

            $magia = Magia::updateOrCreate(
                ['nome' => $data['nome'], 'versao' => $data['versao']],
                $data
            );

            $sync = [];
            foreach ($classesData as $nomeClasse => $nivel) {
                if (isset($classesMap[$nomeClasse])) {
                    $sync[$classesMap[$nomeClasse]] = ['nivel' => $nivel];
                }
            }
            $magia->classes()->sync($sync);
        }
